<?php
namespace App\Http\Controllers\Finance;
use App\Http\Controllers\Controller; use App\Models\Purchase; use App\Models\Approval; use App\Models\EggCollection; use App\Models\FeedConsumption; use App\Models\HealthEvent; use App\Services\PoultryPerformanceService; use Illuminate\Http\Request; use Illuminate\Http\RedirectResponse; use Illuminate\View\View;
class FarmOperationsController extends Controller {
 public function purchases(Request $r):View {abort_unless($r->user()->canAccess('purchases'),403);$q=Purchase::with('recorder')->latest('purchased_on');if($r->filled('status'))$q->where('status',$r->query('status'));return view('finance.farm-operations.purchases',['items'=>$q->paginate(25)->withQueryString(),'total'=>Purchase::sum('total_cost'),'pending'=>Purchase::whereIn('status',['submitted','ceo_approved'])->sum('total_cost')]);}
 public function storePurchase(Request $r):RedirectResponse {abort_unless($r->user()->canDo('purchases','create'),403);$d=$r->validate(['purchased_on'=>['required','date'],'supplier_name'=>['required','string','max:160'],'invoice_number'=>['nullable','string','max:80'],'category'=>['required','in:Feed,Medication,Vaccine,Equipment,Repairs,Fuel,Utilities,Farm supplies,Other'],'item'=>['required','string','max:160'],'unit'=>['nullable','string','max:40'],'quantity'=>['required','numeric','min:0.01'],'unit_cost'=>['required','numeric','min:0'],'payment_status'=>['required','in:unpaid,part_paid,paid'],'notes'=>['nullable','string','max:2000']]);$d['total_cost']=$d['quantity']*$d['unit_cost'];Purchase::create($d+['status'=>'draft','recorded_by'=>$r->user()->id]);return back()->with('status','Purchase saved as draft.');}
 public function submitPurchase(Request $r,Purchase $purchase):RedirectResponse {abort_unless($r->user()->canDo('purchases','edit'),403);abort_unless($purchase->status==='draft',422);$purchase->update(['status'=>'submitted']);$a=$purchase->approvals()->create(['module_key'=>'purchases','department_id'=>$r->user()->department_id,'submitted_by'=>$r->user()->id,'submitted_at'=>now(),'submission_note'=>'Purchase from '.$purchase->supplier_name.': '.$purchase->item,'required_levels'=>2,'due_at'=>now()->addDays(2)]);$a->steps()->createMany([['stage'=>1,'role_code'=>'ceo','status'=>'pending'],['stage'=>2,'role_code'=>'director','status'=>'waiting']]);return back()->with('status','Purchase sent to the CEO for review.');}
 public function production(Request $r):View {abort_unless($r->user()->canAccess('production'),403);$from=$r->date('from')?->toDateString()??now()->startOfMonth()->toDateString();$to=$r->date('to')?->toDateString()??now()->toDateString();$rows=PoultryPerformanceService::forPeriod($from,$to);return view('finance.farm-operations.production',compact('rows','from','to'));}
 public function veterinary(Request $r):View {abort_unless($r->user()->canAccess('veterinary'),403);$from=$r->date('from')?->toDateString()??now()->startOfMonth()->toDateString();$to=$r->date('to')?->toDateString()??now()->toDateString();$events=HealthEvent::with(['batch','medication'])->whereBetween('occurred_on',[$from,$to])->latest('occurred_on')->paginate(25)->withQueryString();$total=HealthEvent::whereBetween('occurred_on',[$from,$to])->sum('cost');return view('finance.farm-operations.veterinary',compact('events','total','from','to'));}
}
